# REPORT LOGOS
# Embedded so the report exports work without needing separate logo files.
# ---------------------------------------------------------------------------
REPORT_LOGOS = {
    "yall": "",
    "friends": "",
    "fghr": "",
    "lef": "",
    "urgent": "",
    "mortenson": "",
}
_REPORT_LOGO_FILES = {}


def _report_logo_path(key):
    """Materialize an embedded report logo to a temporary image file."""
    if not key or key not in REPORT_LOGOS:
        return None
    if key in _REPORT_LOGO_FILES and os.path.exists(_REPORT_LOGO_FILES[key]):
        return _REPORT_LOGO_FILES[key]
    ext = ".png" if key in ("friends", "lef", "mortenson") else ".jpg"
    fd, path = tempfile.mkstemp(prefix=f"yall_report_{key}_", suffix=ext)
    os.close(fd)
    with open(path, "wb") as f:
        f.write(base64.b64decode(REPORT_LOGOS[key]))
    _REPORT_LOGO_FILES[key] = path
    return path


def _project_report_logo_keys(p):
    """Return the exact logo combination assigned to each project/funder."""
    project_name = str(p.get("name", "")).strip().lower()
    project_id = str(p.get("id", "")).strip().lower()
    short_name = str(p.get("short_name", "")).strip().lower()
    funder = str(p.get("funder", "")).strip().lower()

    text = " ".join([project_id, project_name, short_name, funder])

    # Every report carries the YALL logo on the left.
    left = "yall"
    middle = None
    right = None

    # Explicit project/funder mapping.  This prevents the Mortenson logo
    # from being missed if the project is renamed or its ID changes.
    if (
        project_name == "women agricultural resilience initiative"
        or "women agricultural resilience initiative" in text
        or "mortenson family foundation" in funder
        or "mortenson family foundation" in text
    ):
        right = "mortenson"
    elif "agro" in text:
        right = "friends"
    elif "legal" in text and "empower" in text:
        middle = "lef"
        right = "fghr"
    elif (
        (("women's rights" in text or "womens rights" in text or "women rights" in text)
         and ("anti-mining" in text or "anti mining" in text))
        or "urgent action fund" in text
        or ("urgent" in funder and "action" in funder)
    ):
        right = "urgent"

    return left, middle, right


