def _pdf_safe(text):
    """The built-in PDF font only supports latin-1 characters. Coordinator
    notes, project names, etc. can contain characters outside that (smart
    quotes, em dashes, ...) which would otherwise crash report generation.
    This swaps common cases for plain ASCII and safely drops anything else
    left over, so a report can never fail to generate because of this."""
    if text is None:
        return ""
    text = str(text)
    for bad, good in {
        "\u2014": "-", "\u2013": "-",
        "\u2018": "'", "\u2019": "'",
        "\u201c": '"', "\u201d": '"',
        "\u2026": "...", "\u00b7": "-",
    }.items():
        text = text.replace(bad, good)
    return text.encode("latin-1", "replace").decode("latin-1")


def _report_status_summary(report_df):
    """Return status counts including timing-aware categories."""
    counts = report_df["Status"].value_counts().to_dict() if not report_df.empty else {}
    return {
        "total": len(report_df),
        "On track": int(counts.get("On track", 0)),
        "In progress": int(counts.get("In progress", 0)),
        "At risk": int(counts.get("At risk", 0)),
        "Behind": int(counts.get("Behind", 0)),
        "Not yet due": int(counts.get("Not yet due", 0)),
        "Not yet reported": int(counts.get("Not yet reported", 0)),
    }


def _report_value(v):
    """Consistent, donor-friendly display for numeric/text values."""
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return "N/A"
    try:
        f = float(v)
        if pd.isna(f):
            return "N/A"
        return f"{f:g}"
    except (TypeError, ValueError):
        return str(v)


def _report_period_note(period_label):
    if period_label == "All time":
        return ("This report presents cumulative progress using all monitoring records available "
                "in the system. 'This period' reflects activity recorded in the selected view.")
    return ("Cumulative achievement reflects records available up to the end of the selected "
            "reporting period. 'This period' reflects only observations recorded within that period.")


def generate_pdf_report(p, report_df, period_label, notes_df):
    """Build a donor-facing PDF while preserving the exact dashboard data."""
    left_logo, middle_logo, right_logo = _project_report_logo_keys(p)
    logo_paths = {
        "left": _report_logo_path(left_logo),
        "middle": _report_logo_path(middle_logo),
        "right": _report_logo_path(right_logo),
    }

    font_dir = r"C:\Windows\Fonts"
    times_regular = os.path.join(font_dir, "times.ttf")
    times_bold = os.path.join(font_dir, "timesbd.ttf")
    times_italic = os.path.join(font_dir, "timesi.ttf")
    times_bolditalic = os.path.join(font_dir, "timesbi.ttf")

    class ReportPDF(FPDF):
        def header(self):
            y = 5
            if logo_paths["left"]:
                self.image(logo_paths["left"], x=12, y=y, h=16)
            if logo_paths["middle"]:
                self.image(logo_paths["middle"], x=135, y=y + 1, h=13)
            if logo_paths["right"]:
                self.image(logo_paths["right"], x=250, y=y + 1, h=14)
            self.set_y(25)

        def footer(self):
            self.set_y(-10)
            self.set_font(font_family, "", 11)
            self.set_text_color(100, 100, 100)
            self.cell(0, 5, f"YALL M&E System | {period_label} | Page {self.page_no()}", align="C")
            self.set_text_color(0, 0, 0)

    pdf = ReportPDF(orientation="L", unit="mm", format="A4")
    font_family = "TimesNewRoman"
    if all(os.path.exists(x) for x in (times_regular, times_bold, times_italic, times_bolditalic)):
        pdf.add_font("TimesNewRoman", "", times_regular)
        pdf.add_font("TimesNewRoman", "B", times_bold)
        pdf.add_font("TimesNewRoman", "I", times_italic)
        pdf.add_font("TimesNewRoman", "BI", times_bolditalic)
    else:
        font_family = "Times"

    pdf.set_auto_page_break(auto=True, margin=14)
    pdf.set_margins(12, 28, 12)
    pdf.add_page()

    # ---------- Cover / report identity ----------
    pdf.set_font(font_family, "B", 12)
    pdf.cell(0, 8, "YOUTH ACTION LEAD LIBERIA", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font(font_family, "I", 11)
    pdf.cell(0, 5, "Monitoring, Evaluation, Accountability & Learning", new_x="LMARGIN", new_y="NEXT")
    pdf.ln(3)

    pdf.set_font(font_family, "B", 12)
    pdf.multi_cell(0, 7, _pdf_safe(p["name"]), new_x="LMARGIN", new_y="NEXT")
    pdf.set_font(font_family, "", 11)
    meta = [
        f"Funder: {p['funder']}",
        f"Implementation area: {p['locations']}",
        f"Reporting period: {period_label}",
        f"Report generated: {datetime.date.today().strftime('%d %b %Y')}",
    ]
    for line in meta:
        pdf.cell(0, 5, _pdf_safe(line), new_x="LMARGIN", new_y="NEXT")

    pdf.ln(3)
    pdf.set_font(font_family, "B", 12)
    pdf.cell(0, 6, "Project objective", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font(font_family, "", 11)
    pdf.multi_cell(0, 5, _pdf_safe(p["objective"]), new_x="LMARGIN", new_y="NEXT")

    # ---------- Performance snapshot ----------
    summary = _report_status_summary(report_df)
    pdf.ln(4)
    pdf.set_font(font_family, "B", 12)
    pdf.cell(0, 6, "Performance snapshot", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font(font_family, "", 11)
    pdf.multi_cell(0, 4.5, _pdf_safe(
        f"{summary['total']} indicators: {summary['On track']} on track, {summary['In progress']} in progress, "
        f"{summary['At risk']} at risk, {summary['Behind']} behind, "
        f"{summary['Not yet due']} not yet due and {summary['Not yet reported']} not yet reported. "
        + _report_period_note(period_label)
    ), new_x="LMARGIN", new_y="NEXT")

    status_colors = {
        "On track": (220, 252, 231), "In progress": (219, 234, 254),
        "At risk": (254, 243, 199), "Behind": (254, 226, 226),
        "Not yet due": (226, 232, 240), "Not yet reported": (237, 233, 254),
    }
    snap = [["Indicators", str(summary["total"]), "On track", str(summary["On track"]),
             "In progress", str(summary["In progress"]), "At risk", str(summary["At risk"]),
             "Behind", str(summary["Behind"]), "Not yet due", str(summary["Not yet due"]),
             "Not yet reported", str(summary["Not yet reported"])]]
    pdf.ln(2)
    snapshot_widths = (19, 8, 19, 8, 23, 8, 18, 8, 18, 8, 22, 8, 24, 8)
    snapshot_align = ("LEFT", "RIGHT", "LEFT", "RIGHT", "LEFT", "RIGHT", "LEFT", "RIGHT", "LEFT", "RIGHT", "LEFT", "RIGHT", "LEFT", "RIGHT")
    with pdf.table(col_widths=snapshot_widths, text_align=snapshot_align, line_height=4.5) as table:
        row = table.row()
        for index, value in enumerate(snap[0]):
            status_index = {2: "On track", 3: "On track", 4: "In progress", 5: "In progress", 6: "At risk", 7: "At risk", 8: "Behind", 9: "Behind", 10: "Not yet due", 11: "Not yet due", 12: "Not yet reported", 13: "Not yet reported"}.get(index)
            if status_index:
                row.cell(value, style=FontFace(fill_color=status_colors[status_index]))
            else:
                row.cell(value)

    # ---------- Key findings ----------
    pdf.ln(5)
    pdf.set_font(font_family, "B", 12)
    pdf.cell(0, 6, "Key findings", new_x="LMARGIN", new_y="NEXT")

    pdf.ln(1)
    pdf.set_font(font_family, "B", 12)
    pdf.cell(0, 6, "Achievements", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font(font_family, "", 11)
    achieved = report_df[report_df["Status"] == "On track"].head(5)
    if achieved.empty:
        pdf.multi_cell(0, 4.5, "No indicators are currently classified as on track.", new_x="LMARGIN", new_y="NEXT")
    else:
        for _, r in achieved.iterrows():
            pdf.multi_cell(0, 4.5, _pdf_safe(f"- {r['Indicator']}: {_report_value(r['Cumulative Achievement'])} against target {_report_value(r['Target (life of project)'])}."), new_x="LMARGIN", new_y="NEXT")

    pdf.ln(2)
    pdf.set_font(font_family, "B", 12)
    pdf.cell(0, 6, "Areas requiring attention", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font(font_family, "", 11)
    attention = report_df[report_df["Status"].isin(["Behind", "At risk", "Not yet reported"])].head(6)
    if attention.empty:
        pdf.multi_cell(0, 4.5, "No behind, at-risk, or not-yet-reported indicators are identified in this view.", new_x="LMARGIN", new_y="NEXT")
    else:
        for _, r in attention.iterrows():
            pdf.multi_cell(0, 4.5, _pdf_safe(f"- {r['Status']}: {r['Indicator']} — {_report_value(r['Cumulative Achievement'])} against target {_report_value(r['Target (life of project)'])}."), new_x="LMARGIN", new_y="NEXT")

    # ---------- Main donor table ----------
    pdf.ln(5)
    pdf.set_font(font_family, "B", 12)
    pdf.cell(0, 6, "Indicator performance", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font(font_family, "", 11)
    pdf.multi_cell(0, 4.5, "This summary table is intended for management and donor review. Full source, collection, variance and beneficiary detail is provided in Annex 1.", new_x="LMARGIN", new_y="NEXT")
    pdf.ln(2)

    pdf.set_font(font_family, "B", 11)
    main_widths = (80, 19, 19, 23, 23, 18, 25)
    with pdf.table(col_widths=main_widths,
                   text_align=("LEFT", "RIGHT", "RIGHT", "RIGHT", "RIGHT", "RIGHT", "LEFT"),
                   line_height=4.5) as table:
        header = table.row()
        for h in ["Indicator", "Baseline", "Target", "Cumulative", "This period", "% Target", "Status"]:
            header.cell(h)
        pdf.set_font(font_family, "", 11)
        for _, r in report_df.iterrows():
            row = table.row()
            row.cell(_pdf_safe(str(r["Indicator"])))
            row.cell(_report_value(r["Baseline"]))
            row.cell(_report_value(r["Target (life of project)"]))
            row.cell(_report_value(r["Cumulative Achievement"]))
            row.cell(_pdf_safe(str(r["This Period Achievement"])))
            row.cell(_report_value(r["% of Target"]))
            row.cell(_pdf_safe(str(r["Status"])), style=FontFace(fill_color=status_colors.get(r["Status"], (255, 255, 255))))

    pdf.ln(3)
    pdf.set_font(font_family, "", 7)
    pdf.multi_cell(0, 4.5, _pdf_safe(
        "Data interpretation: 'no data this period' means that no new observation was recorded in the selected period; it is not automatically a zero achievement. "
        "Status uses the Gantt timing window. 'Not yet due' means the scheduled activity/measurement window has not started; 'Not yet reported' means the window is active but no observation is recorded; 'In progress' means evidence exists while the window is still open. "
        "Only after the scheduled window closes is the achievement level used to classify At risk or Behind."
    ), new_x="LMARGIN", new_y="NEXT")

    # ---------- Annex 1: complete M&E table ----------
    pdf.add_page()
    pdf.set_font(font_family, "B", 12)
    pdf.cell(0, 7, _pdf_safe("Annex 1 - Detailed Indicator Performance"), new_x="LMARGIN", new_y="NEXT")
    pdf.set_font(font_family, "", 11)
    pdf.multi_cell(0, 4.5, "Complete M&E detail for the selected reporting period. Values are taken directly from the dashboard report table.", new_x="LMARGIN", new_y="NEXT")
    pdf.ln(2)

    cols = ["Indicator", "Baseline", "Target (life of project)", "Cumulative Achievement",
            "This Period Achievement", "% of Target", "Status", "Gantt Timing", "Source of Data",
            "Collection Dates (this period)", "Variance", "Target Beneficiaries",
            "Actual Reached", "Male", "Female"]
    widths = (48, 11, 12, 15, 15, 10, 16, 27, 29, 24, 11, 16, 14, 11, 11)
    pdf.set_font(font_family, "B", 11)
    with pdf.table(col_widths=widths,
                   text_align=("LEFT", "RIGHT", "RIGHT", "RIGHT", "RIGHT", "RIGHT", "LEFT", "LEFT", "LEFT", "RIGHT", "RIGHT", "RIGHT", "RIGHT", "RIGHT", "RIGHT"),
                   line_height=4.2) as table:
        header = table.row()
        for h in cols:
            header.cell(h)
        pdf.set_font(font_family, "", 11)
        for _, r in report_df.iterrows():
            row = table.row()
            for col in cols:
                value = r[col]
                if col in ("Baseline", "Target (life of project)", "Cumulative Achievement", "% of Target", "Variance"):
                    value = _report_value(value)
                else:
                    value = _pdf_safe(str(value))
                if col == "Status":
                    row.cell(value, style=FontFace(fill_color=status_colors.get(r["Status"], (255, 255, 255))))
                else:
                    row.cell(value)

    # ---------- Field notes ----------
    pdf.add_page()
    pdf.set_font(font_family, "B", 12)
    pdf.cell(0, 7, _pdf_safe(f"Field Monitoring Notes - {period_label}"), new_x="LMARGIN", new_y="NEXT")
    pdf.set_font(font_family, "", 11)
    if notes_df.empty:
        pdf.multi_cell(0, 5, "No narrative updates were recorded for this reporting period.", new_x="LMARGIN", new_y="NEXT")
    else:
        for _, row in notes_df.iterrows():
            date_str = row["obs_date"].strftime("%d %b %Y") if pd.notnull(row["obs_date"]) else "Date not recorded"
            pdf.set_font(font_family, "B", 11)
            pdf.multi_cell(0, 4.5, _pdf_safe(f"{date_str} — {row['indicator_name']}"), new_x="LMARGIN", new_y="NEXT")
            pdf.set_font(font_family, "", 11)
            community = str(row.get("community", "")).strip()
            prefix = f"Community: {community}. " if community and community != "nan" else ""
            pdf.multi_cell(0, 4.5, _pdf_safe(prefix + str(row["note"])), new_x="LMARGIN", new_y="NEXT")
            pdf.ln(2)

    pdf.set_font(font_family, "B", 12)
    pdf.cell(0, 5, "Data quality and interpretation note", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font(font_family, "", 11)
    pdf.multi_cell(0, 4.5, _pdf_safe(
        "This report reflects monitoring records available for the selected reporting period. "
        "Where no new observation was recorded, the report displays 'no data this period' rather than estimating an achievement. "
        "Status is timing-aware and uses the Gantt activity/measurement window; the system does not assume that elapsed project time equals expected achievement. "
        "Cumulative achievement is calculated from records available up to the end of the selected period."
    ), new_x="LMARGIN", new_y="NEXT")

    return bytes(pdf.output())


def generate_docx_report(p, report_df, period_label, notes_df):
    """Build the same donor-facing report as the PDF, in editable Word format."""
    import io
    from docx import Document
    from docx.oxml.ns import qn
    from docx.oxml import OxmlElement
    from docx.enum.section import WD_ORIENT
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.shared import Pt, Cm

    doc = Document()
    section = doc.sections[0]
    section.orientation = WD_ORIENT.LANDSCAPE
    section.page_width, section.page_height = section.page_height, section.page_width
    section.left_margin = section.right_margin = Cm(1.5)
    section.top_margin = Cm(2.4)
    section.bottom_margin = Cm(1.5)

    # Report logo header: YALL always left; project-specific partner logos
    # follow the arrangement supplied in Logo.docx.
    left_logo, middle_logo, right_logo = _project_report_logo_keys(p)
    header = section.header
    logo_table = header.add_table(rows=1, cols=3, width=Cm(27))
    logo_table.autofit = False
    widths = [Cm(6), Cm(10), Cm(6)]
    for cell, width in zip(logo_table.rows[0].cells, widths):
        cell.width = width
        cell.vertical_alignment = 1
    for cell in logo_table.rows[0].cells:
        cell.paragraphs[0].paragraph_format.space_after = Pt(0)
    if left_logo:
        r = logo_table.cell(0, 0).paragraphs[0].add_run()
        r.add_picture(_report_logo_path(left_logo), height=Cm(1.45))
        logo_table.cell(0, 0).paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.LEFT
    if middle_logo:
        r = logo_table.cell(0, 1).paragraphs[0].add_run()
        r.add_picture(_report_logo_path(middle_logo), height=Cm(1.15))
        logo_table.cell(0, 1).paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
    if right_logo:
        r = logo_table.cell(0, 2).paragraphs[0].add_run()
        r.add_picture(_report_logo_path(right_logo), height=Cm(1.25))
        logo_table.cell(0, 2).paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.RIGHT

    # Footer / page numbering.
    footer = section.footer.paragraphs[0]
    footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
    footer_run = footer.add_run(f"YALL M&E System | {period_label} | ")
    footer_run.font.size = Pt(11)
    fld = OxmlElement("w:fldSimple")
    fld.set(qn("w:instr"), "PAGE")
    footer._p.append(fld)

    styles = doc.styles
    styles["Normal"].font.name = "Times New Roman"
    styles["Normal"].font.size = Pt(11)
    for style_name, size in [("Title", 12), ("Heading 1", 12), ("Heading 2", 12), ("Heading 3", 12)]:
        styles[style_name].font.name = "Times New Roman"
        styles[style_name].font.size = Pt(size)

    doc.add_heading("YOUTH ACTION LEAD LIBERIA", level=1)
    sub = doc.add_paragraph("Monitoring, Evaluation, Accountability & Learning")
    sub.runs[0].italic = True
    doc.add_heading(p["name"], level=2)

    for label, value in [
        ("Funder", p["funder"]),
        ("Implementation area", p["locations"]),
        ("Reporting period", period_label),
        ("Report generated", datetime.date.today().strftime("%d %b %Y")),
    ]:
        para = doc.add_paragraph()
        run = para.add_run(f"{label}: ")
        run.bold = True
        para.add_run(str(value))

    doc.add_heading("Project objective", level=3)
    obj = doc.add_paragraph(p["objective"])
    obj.runs[0].italic = True

    status_fills = {
        "On track": "DCFCE7", "In progress": "DBEAFE", "At risk": "FEF3C7",
        "Behind": "FEE2E2", "Not yet due": "E2E8F0", "Not yet reported": "EDE9FE",
    }
    def shade(cell, hex_color):
        tc_pr = cell._tc.get_or_add_tcPr()
        shd = OxmlElement("w:shd")
        shd.set(qn("w:fill"), hex_color)
        tc_pr.append(shd)

    summary = _report_status_summary(report_df)
    doc.add_heading("Performance snapshot", level=2)
    doc.add_paragraph(
        f"{summary['total']} indicators: {summary['On track']} on track, {summary['In progress']} in progress, "
        f"{summary['At risk']} at risk, {summary['Behind']} behind, "
        f"{summary['Not yet due']} not yet due and {summary['Not yet reported']} not yet reported. "
        + _report_period_note(period_label)
    )
    snap = doc.add_table(rows=1, cols=14)
    snap.style = "Table Grid"
    vals = ["Indicators", summary["total"], "On track", summary["On track"], "In progress", summary["In progress"], "At risk", summary["At risk"], "Behind", summary["Behind"], "Not yet due", summary["Not yet due"], "Not yet reported", summary["Not yet reported"]]
    for i, value in enumerate(vals):
        snap.rows[0].cells[i].text = str(value)
        for run in snap.rows[0].cells[i].paragraphs[0].runs:
            run.font.size = Pt(11)
            run.bold = True
    for status_index, status in enumerate(STATUS_ORDER, start=1):
        shade(snap.rows[0].cells[status_index * 2], status_fills[status])
        shade(snap.rows[0].cells[status_index * 2 + 1], status_fills[status])

    doc.add_heading("Key findings", level=2)
    doc.add_heading("Achievements", level=3)
    achieved = report_df[report_df["Status"] == "On track"].head(5)
    if achieved.empty:
        doc.add_paragraph("No indicators are currently classified as on track.")
    else:
        for _, r in achieved.iterrows():
            doc.add_paragraph(f"{r['Indicator']}: {_report_value(r['Cumulative Achievement'])} against target {_report_value(r['Target (life of project)'])}.", style="List Bullet")

    doc.add_heading("Areas requiring attention", level=3)
    attention = report_df[report_df["Status"].isin(["Behind", "At risk", "Not yet reported"])].head(6)
    if attention.empty:
        doc.add_paragraph("No behind, at-risk, or not-yet-reported indicators are identified in this view.")
    else:
        for _, r in attention.iterrows():
            doc.add_paragraph(f"{r['Status']}: {r['Indicator']} — {_report_value(r['Cumulative Achievement'])} against target {_report_value(r['Target (life of project)'])}.", style="List Bullet")

    doc.add_heading("Indicator performance", level=2)
    doc.add_paragraph("This summary table is intended for management and donor review. Full M&E detail is provided in Annex 1.")
    main_cols = ["Indicator", "Baseline", "Target (life of project)", "Cumulative Achievement", "This Period Achievement", "% of Target", "Status"]
    main_table = doc.add_table(rows=1, cols=len(main_cols))
    main_table.style = "Table Grid"
    for i, h in enumerate(main_cols):
        cell = main_table.rows[0].cells[i]
        cell.text = h
        for run in cell.paragraphs[0].runs:
            run.bold = True
            run.font.size = Pt(11)
    for _, r in report_df.iterrows():
        cells = main_table.add_row().cells
        for i, col in enumerate(main_cols):
            cells[i].text = _report_value(r[col]) if col != "Indicator" and col != "This Period Achievement" and col != "Status" else str(r[col])
            for par in cells[i].paragraphs:
                for run in par.runs:
                    run.font.size = Pt(11)
        shade(cells[main_cols.index("Status")], status_fills.get(r["Status"], "FFFFFF"))

    doc.add_page_break()
    doc.add_heading("Annex 1 — Detailed Indicator Performance", level=1)
    doc.add_paragraph("Complete M&E detail for the selected reporting period. Values are taken directly from the dashboard report table.")
    cols = ["Indicator", "Baseline", "Target (life of project)", "Cumulative Achievement",
            "This Period Achievement", "% of Target", "Status", "Gantt Timing", "Source of Data",
            "Collection Dates (this period)", "Variance", "Target Beneficiaries",
            "Actual Reached", "Male", "Female"]
    table = doc.add_table(rows=1, cols=len(cols))
    table.style = "Table Grid"
    for i, h in enumerate(cols):
        table.rows[0].cells[i].text = h
        for run in table.rows[0].cells[i].paragraphs[0].runs:
            run.bold = True
            run.font.size = Pt(11)
    for _, r in report_df.iterrows():
        cells = table.add_row().cells
        for i, col in enumerate(cols):
            value = _report_value(r[col]) if col in ("Baseline", "Target (life of project)", "Cumulative Achievement", "% of Target", "Variance") else str(r[col])
            cells[i].text = value
            for par in cells[i].paragraphs:
                for run in par.runs:
                    run.font.size = Pt(11)
        shade(cells[cols.index("Status")], status_fills.get(r["Status"], "FFFFFF"))

    doc.add_page_break()
    doc.add_heading(f"Field Monitoring Notes — {period_label}", level=1)
    if notes_df.empty:
        doc.add_paragraph("No narrative updates were recorded for this reporting period.")
    else:
        for _, row in notes_df.iterrows():
            date_str = row["obs_date"].strftime("%d %b %Y") if pd.notnull(row["obs_date"]) else "Date not recorded"
            para = doc.add_paragraph()
            run = para.add_run(f"{date_str} — {row['indicator_name']}")
            run.bold = True
            community = str(row.get("community", "")).strip()
            if community and community != "nan":
                para.add_run(f" | Community: {community}")
            para.add_run(f"\n{str(row['note'])}")

    doc.add_heading("Data quality and interpretation note", level=2)
    doc.add_paragraph(
        "This report reflects monitoring records available for the selected reporting period. "
        "Where no new observation was recorded, the report displays 'no data this period' rather than estimating an achievement. "
        "Status is timing-aware and uses the Gantt activity/measurement window; the system does not assume that elapsed project time equals expected achievement. "
        "Cumulative achievement is calculated from records available up to the end of the selected period."
    )

    buf = io.BytesIO()
    doc.save(buf)
    return buf.getvalue()

def get_period_range(choice, month=None, year=None, custom_start=None, custom_end=None):
    """Returns (period_start, period_end) as datetime.date, or (None, None)
    for 'All time' (no filtering)."""
    if choice == "Specific month":
        period_start = datetime.date(year, month, 1)
        last_day = calendar.monthrange(year, month)[1]
        period_end = datetime.date(year, month, last_day)
        return period_start, period_end
    if choice == "Custom range":
        return custom_start, custom_end
    return None, None


def period_achievement(period_df, indicator):
    """The raw achievement within a (possibly narrow) date-filtered slice of
    data — NOT compared back to the indicator's overall baseline/target, just
    'what happened in this window'. Returns None when nothing was logged in
    the window, so it displays as blank rather than a misleading zero."""
    ind_id = indicator["id"]
    if indicator["type"] == "average":
        avg, n, _ = average_group_changes(period_df, ind_id)
        return avg if n else None
    if indicator["type"] == "percent":
        total_a, total_i = sum_percent_components(period_df, ind_id)
        if total_a and total_a > 0:
            return total_i / total_a * 100.0
        return None
    total = sum_values(period_df, ind_id)
    return total


def render_reports(user, df):
    st.title("Reports")
    vp = visible_projects(user)
    ids = [p["id"] for p in vp]
    names = {p["id"]: p["short_name"] for p in vp}
    selected = st.selectbox("Project", ids, format_func=lambda i: names[i]) if len(vp) > 1 else ids[0]
    p = project_by_id(selected)
    inds = indicators_for(selected)

    st.markdown(f"### {p['name']} — Progress Report")
    st.caption(f"Funder: {p['funder']} | Location: {p['locations']} | Generated {datetime.date.today().strftime('%d %b %Y')}")
    st.markdown(f"> {p['objective']}")

    st.subheader("Reporting period")
    period_choice = st.radio("Period", ["All time", "Specific month", "Custom range"], horizontal=True, label_visibility="collapsed")
    period_start = period_end = None
    if period_choice == "Specific month":
        c1, c2 = st.columns(2)
        today = datetime.date.today()
        month = c1.selectbox("Month", list(range(1, 13)), format_func=lambda m: calendar.month_name[m], index=today.month - 1)
        year = c2.number_input("Year", min_value=2024, max_value=2035, value=today.year, step=1)
        period_start, period_end = get_period_range("Specific month", month=month, year=year)
    elif period_choice == "Custom range":
        c1, c2 = st.columns(2)
        period_start = c1.date_input("From", value=datetime.date.today().replace(day=1))
        period_end = c2.date_input("To", value=datetime.date.today())

    # Prepare two views of the data: cumulative-to-date (as of period end, or
    # everything if "All time"), and period-only (just entries inside the
    # chosen window). All existing aggregation logic is reused unchanged —
    # only the dataframe fed into it differs, same trick as Community View.
    df_dated = df.copy()
    df_dated["obs_date"] = pd.to_datetime(df_dated["obs_date"], errors="coerce")
    if period_end is not None:
        cumulative_df = df_dated[df_dated["obs_date"] <= pd.Timestamp(period_end)]
    else:
        cumulative_df = df_dated
    if period_start is not None and period_end is not None:
        period_df = df_dated[(df_dated["obs_date"] >= pd.Timestamp(period_start)) & (df_dated["obs_date"] <= pd.Timestamp(period_end))]
    else:
        period_df = df_dated

    if period_choice == "All time":
        st.caption("Showing all-time cumulative progress.")
        period_label = "All time"
    else:
        st.caption(f"Period: {period_start.strftime('%d %b %Y')} to {period_end.strftime('%d %b %Y')}. "
                   "\"Cumulative\" = progress as of the end of this period. \"This period\" = only activity logged within it.")
        period_label = f"{period_start.strftime('%d %b %Y')} to {period_end.strftime('%d %b %Y')}"

    rows = []
    for ind in inds:
        cum = current_value(cumulative_df, ind)
        pct = pct_complete(ind, cumulative_df)
        label, _ = status_of(ind, pct, cumulative_df, period_end)
        this_period = period_achievement(period_df, ind)
        unit = "%" if ind["type"] in ("percent", "average") else ind["unit"]
        variance = round(ind["target"] - cum, 1)
        dates = collection_dates_for(period_df, ind["id"])
        dates_str = ", ".join(dates[:3]) + (f" (+{len(dates)-3} more)" if len(dates) > 3 else "") if dates else "—"

        # These columns mix numbers with text ("N/A", "not disaggregated") across
        # different rows, which breaks Streamlit's table display if left as raw
        # numbers on some rows and strings on others — so everything here is
        # formatted as a plain string up front, consistently.
        if ind.get("gender_disagg"):
            m, f = sum_gender(cumulative_df, ind["id"])
            target_beneficiaries = f"{ind['target']:g}"
            actual_reached = f"{cum:.1f}"
            male_val = f"{m:.0f}" if m is not None else "not disaggregated"
            female_val = f"{f:.0f}" if f is not None else "not disaggregated"
        else:
            target_beneficiaries = "N/A"
            actual_reached = "N/A"
            male_val = "N/A"
            female_val = "N/A"
        this_period_str = f"{this_period:.1f}" if this_period is not None else "no data this period"

        rows.append({
            "Indicator": ind["name"],
            "Baseline": ind["baseline"],
            "Target (life of project)": ind["target"],
            "Cumulative Achievement": round(cum, 1),
            "This Period Achievement": this_period_str,
            "% of Target": round(pct),
            "Status": label,
            "Gantt Timing": GANTT_TIMING.get(ind["id"], (None, None, "No timing mapping in source"))[2],
            "Source of Data": ind.get("mov", ""),
            "Collection Dates (this period)": dates_str,
            "Variance": variance,
            "Target Beneficiaries": target_beneficiaries,
            "Actual Reached": actual_reached,
            "Male": male_val,
            "Female": female_val,
        })
    report_df = pd.DataFrame(rows)
    st.dataframe(report_df, use_container_width=True, hide_index=True)
    st.caption("Status is timing-aware: the Gantt is used to determine whether an indicator is due. The system does not assume project elapsed time equals expected achievement. "
               "\"Variance\" is life-of-project target minus cumulative achievement — positive means still short of target, negative means it has been exceeded. "
               "The written explanation for any variance is yours to add — this table gives you the numbers and dates to write it from.")

    # Build the notes dataframe ONCE, with the indicator name already resolved,
    # so the on-screen list and the PDF/Word exports show the identical set —
    # filtered to the SAME period the person is looking at, not all history.
    proj_ids = {i["id"] for i in inds}
    notes_df = period_df[period_df["indicator"].isin(proj_ids) & period_df["note"].notna()
                          & (period_df["note"].astype(str).str.strip() != "")].copy()
    if not notes_df.empty:
        notes_df = notes_df.sort_values("obs_date", ascending=False)
        notes_df["indicator_name"] = notes_df["indicator"].map(
            lambda iid: next((i["name"] for i in inds if i["id"] == iid), iid)
        )

    csv_bytes = report_df.to_csv(index=False).encode("utf-8")
    dl1, dl2, dl3 = st.columns(3)
    with dl1:
        st.download_button("Download table as CSV", csv_bytes, file_name=f"{selected}_report.csv", mime="text/csv")
    with dl2:
        if st.button("Generate PDF report"):
            with st.spinner("Building PDF..."):
                pdf_bytes = generate_pdf_report(p, report_df, period_label, notes_df)
            st.download_button("Download PDF report", pdf_bytes, file_name=f"{selected}_report.pdf", mime="application/pdf")
    with dl3:
        if st.button("Generate Word report"):
            with st.spinner("Building Word document..."):
                docx_bytes = generate_docx_report(p, report_df, period_label, notes_df)
            st.download_button(
                "Download Word report", docx_bytes, file_name=f"{selected}_report.docx",
                mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            )
    st.caption("The PDF and Word downloads now show exactly this period's figures — the same table and notes you see above, not all-time history.")

    st.subheader("Recent field updates")
    if notes_df.empty:
        st.info("No narrative updates recorded yet for this project in this period.")
    else:
        for _, row in notes_df.head(8).iterrows():
            date_str = row["obs_date"].strftime("%d %b %Y") if pd.notnull(row["obs_date"]) else ""
            where = f" ({row['community']})" if pd.notna(row.get("community")) and str(row.get("community")).strip() else ""
            st.markdown(f"**{date_str}**{where} — *{row['indicator_name']}*: {row['note']}")

    st.caption("Tip: use your browser's Print (Ctrl/Cmd+P) to save this report as a PDF.")


